function u(t){const e=Number(t)||0;return new Intl.NumberFormat("en-LK",{style:"currency",currency:"LKR",minimumFractionDigits:2}).format(e)}function c(t){return t?(t.toDate?t.toDate():new Date(t)).toLocaleString("en-LK",{dateStyle:"medium",timeStyle:"short"}):"—"}function s(t){if(!t)return"—";const e=t.toDate?t.toDate():new Date(t),n=Math.floor((Date.now()-e.getTime())/1e3);if(n<60)return"just now";const o=Math.floor(n/60);if(o<60)return`${o}m ago`;const r=Math.floor(o/60);return r<24?`${r}h ago`:`${Math.floor(r/24)}d ago`}function D(t,e){const n=t.toDate?t.toDate():new Date(t),o=e.toDate?e.toDate():new Date(e);return n.getFullYear()===o.getFullYear()&&n.getMonth()===o.getMonth()&&n.getDate()===o.getDate()}export{u as a,c as f,D as i,s as t};
